        if(긴부호없는값[მფლობელი_ობიექტი]){if((둘째값&192)!=128){긴부호없는값[მფლობელი_ობიექტი]=0;return;}부호없는결과[მფლობელი_ობიექტი]=(부호없는결과[მფლობელი_ობიექტი]<<6)|(둘째값&63);if(--긴부호없는값[მფლობელი_ობიექტი])return;სიმბოლო_კოდირება=부호없는결과[მფლობელი_ობიექტი];}
        else if(둘째값>=0xc2&&둘째값<=0xf4){긴부호없는값[მფლობელი_ობიექტი]=둘째값<0xe0?1:둘째값<0xf0?2:3;부호없는결과[მფლობელი_ობიექტი]=둘째값&((1u<<(6-긴부호없는값[მფლობელი_ობიექტი]))-1);return;}
